import "../../state.js";

/* Teacher workload & contract — the report an Academic Coordinator actually
 * needs, and the first home for `teacherContractLength` (until now a field the
 * UI stored and nothing read).
 *
 * Per teacher: periods, working days, total and isolated gaps, longest run,
 * last-period count, distinct rooms/buildings, supervision duties, and the
 * contract figure with over/under. Sorted by load so the unfair cases surface
 * at the top.
 *
 * computeTeacherWorkload() is pure and exported, so it can be tested (and
 * reused by a future dashboard) without rendering a page.
 */

/** Numeric view of a limit that may be "", "*", "i" or a string number. */
function num(v) {
  if (v == null || v === "" || v === "*" || v === "i") return null;
  const n = parseInt(v, 10);
  return Number.isFinite(n) ? n : null;
}

/** Cards grouped per teacher from whichever index the school carries. */
function cardsOf(school, teacherId) {
  const idx = school._idx || {};
  if (idx.cardsByTeacher && idx.cardsByTeacher[teacherId]) return idx.cardsByTeacher[teacherId];
  const lessons = new Map((school.lessons || []).map((l) => [l.id, l]));
  return (school.cards || []).filter((c) => {
    const l = lessons.get(c.lessonId);
    return l && (l.teacherIds || []).includes(teacherId);
  });
}

function supervisionCount(school, teacherId) {
  return (school.classroomsupervisions || []).filter((s) => s.teacherId === teacherId).length;
}

/**
 * @returns {Array<{id,name,periods,days,dayGaps,isolatedGaps,longestRun,
 *   lastPeriods,rooms,buildings,duties,contract,delta,daysOff}>}
 */
export function computeTeacherWorkload(school, opts) {
  const o = opts || {};
  const daysPerWeek = school.daysPerWeek || 6;
  const periodsPerDay = o.periodsPerDay || school.periodsPerDay || 8;
  const roomById = new Map((school.classrooms || []).map((r) => [r.id, r]));
  const buildingById = new Map((school.buildings || []).map((b) => [b.id, b]));

  return (school.teachers || []).map((t) => {
    const cards = cardsOf(school, t.id) || [];
    const byDay = new Map();
    for (const c of cards) {
      const d = c.day | 0;
      let row = byDay.get(d);
      if (!row) byDay.set(d, row = new Set());
      row.add((c.period | 0) - 1);          // 0-based period inside the day
    }
    let dayGaps = 0, isolated = 0, longest = 0, lastPeriods = 0;
    for (const [, set] of byDay) {
      const ps = [...set].sort((a, b) => a - b);
      if (!ps.length) continue;
      dayGaps += (ps[ps.length - 1] - ps[0] + 1) - ps.length;
      // An "isolated" gap is a single free period between two busy ones — the
      // one a coordinator reads as a wasted slot. Multi-period holes count in
      // `dayGaps` but not here.
      for (let i = 1; i < ps.length; i++) {
        if (ps[i] === ps[i - 1] + 2) isolated += 1;
      }
      let run = 1;
      for (let i = 1; i < ps.length; i++) {
        run = ps[i] === ps[i - 1] + 1 ? run + 1 : 1;
        if (run > longest) longest = run;
      }
      longest = Math.max(longest, 1);
      if (ps.includes(periodsPerDay - 1)) lastPeriods += 1;
    }
    const rooms = new Set();
    const buildings = new Set();
    for (const c of cards) {
      if (!c.classroomId) continue;
      rooms.add(c.classroomId);
      const r = roomById.get(c.classroomId);
      const b = r && (r.buildingId || r.buildingid);
      if (b && buildingById.has(b)) buildings.add(b);
    }
    const cons = t.constraints || {};
    const contract = num(t.teacherContractLength) ?? num(t.contractLength) ?? num(cons.teacherContractLength);
    const periods = cards.length;
    return {
      id: t.id,
      name: t.name || [t.firstName, t.lastName].filter(Boolean).join(" ") || t.id,
      periods,
      days: byDay.size,
      daysOff: Math.max(0, daysPerWeek - byDay.size),
      dayGaps,
      isolatedGaps: isolated,
      longestRun: longest,
      lastPeriods,
      rooms: rooms.size,
      buildings: buildings.size,
      duties: supervisionCount(school, t.id),
      contract,
      delta: contract == null ? null : periods - contract,
    };
  });
}

(function () {
  "use strict";
  const U = window.APP.printTemplateUtils;
  if (!U) return;
  const { el, page, header, footer, emptyPage } = U;

  const PER_PAGE = 30;

  function render(school) {
    if (!school || !(school.teachers || []).length) return [emptyPage("No teachers")];
    const rows = computeTeacherWorkload(school)
      .sort((a, b) => (b.periods - a.periods) || a.name.localeCompare(b.name));

    const pages = [];
    for (let i = 0; i < rows.length; i += PER_PAGE) {
      const chunk = rows.slice(i, i + PER_PAGE);
      const p = page(true);            // landscape: this table is wide
      p.appendChild(header("Teacher workload & contract",
        (school.schoolName || "") + "  ·  page " + (i / PER_PAGE + 1) +
        "/" + Math.ceil(rows.length / PER_PAGE)));

      const tbl = el("table", { style: U.tableCSS() });
      const head = el("tr");
      ["#", "Teacher", "Periods", "Days", "Off", "Gaps", "Isol.", "Max run", "Last",
        "Rooms", "Bldgs", "Duties", "Contract", "±"]
        .forEach((h) => head.appendChild(el("th", { style: U.thCSS() + ";font-size:8.5px" }, h)));
      tbl.appendChild(el("thead", null, head));

      const tbody = el("tbody");
      chunk.forEach((r, idx) => {
        const tr = el("tr");
        const cell = (txt, extra) => tr.appendChild(el("td",
          { style: U.tdCSS() + ";font-size:8.5px" + (extra || "") }, String(txt)));
        cell(i + idx + 1, ";color:#666;text-align:right");
        cell(r.name, ";font-weight:600");
        cell(r.periods, ";text-align:right");
        cell(r.days, ";text-align:right");
        cell(r.daysOff, ";text-align:right");
        cell(r.dayGaps, ";text-align:right");
        cell(r.isolatedGaps, ";text-align:right");
        cell(r.longestRun, ";text-align:right");
        cell(r.lastPeriods, ";text-align:right");
        cell(r.rooms, ";text-align:right");
        cell(r.buildings, ";text-align:right");
        cell(r.duties, ";text-align:right");
        cell(r.contract == null ? "—" : r.contract, ";text-align:right");
        const d = r.delta;
        cell(d == null ? "—" : (d > 0 ? "+" + d : String(d)),
          ";text-align:right;font-weight:600;color:" +
          (d == null ? "#666" : d > 0 ? "#b91c1c" : d < 0 ? "#b45309" : "#047857"));
        tbody.appendChild(tr);
      });
      tbl.appendChild(tbody);
      p.appendChild(tbl);

      const totals = rows.reduce((a, r) => {
        a.periods += r.periods; a.gaps += r.dayGaps; a.isolated += r.isolatedGaps; return a;
      }, { periods: 0, gaps: 0, isolated: 0 });
      p.appendChild(el("div", { style: "margin-top:8px;font-size:9px;color:#666" },
        `Teachers: ${rows.length} · placed periods: ${totals.periods} · gaps: ${totals.gaps} ` +
        `(isolated ${totals.isolated}) · red = over contract, amber = under`));
      p.appendChild(footer());
      pages.push(p);
    }
    return pages;
  }

  window.APP.printTemplates.register("teacher_workload", {
    name: "Teacher workload & contract",
    render,
  });
  window.APP.computeTeacherWorkload = computeTeacherWorkload;
})();
